// Package datecal holds verified date recipes for Go's standard "time"
// package plus calendar conversions (Julian, Hebrew, Hijri, Chinese).
// Every function is tested against ../testdata (generated by
// scripts/datecalc.py, itself verified against independent libraries).
//
// Rules of thumb for Go:
//   - Represent a calendar DATE as time.Time at 00:00 in time.UTC. Doing date
//     maths in a local zone breaks on DST days (a "day" can be 23 or 25 hours).
//   - t.AddDate(0, 1, 0) does NOT clamp: Jan 31 + 1 month = Mar 3 (or Mar 2 in
//     leap years), because time.Date normalises Feb 31 forward. Use AddMonths
//     below when you mean "same day next month, or the last day if shorter".
//   - time.Date normalises out-of-range fields on purpose. That makes some
//     things easy: time.Date(y, m+1, 1, ...) is the first of next month even in
//     December, and time.Date(y, m+1, 0, ...) is the LAST day of month m.
//   - time.Weekday counts Sunday = 0 ... Saturday = 6 (not Monday = 0).
//   - Layout strings use the reference time: "2006-01-02", not "YYYY-MM-DD".
package datecal

import "time"

// Date builds a civil date (UTC midnight). Out-of-range values normalise.
func Date(y int, m time.Month, d int) time.Time {
	return time.Date(y, m, d, 0, 0, 0, 0, time.UTC)
}

// Civil strips the clock and zone: the local calendar date of t, at UTC midnight.
func Civil(t time.Time) time.Time {
	y, m, d := t.Date()
	return Date(y, m, d)
}

// AddDays adds n calendar days (safe: works on UTC civil dates).
func AddDays(t time.Time, n int) time.Time { return t.AddDate(0, 0, n) }

// DaysInMonth returns the length of month m of year y.
func DaysInMonth(y int, m time.Month) int { return Date(y, m+1, 0).Day() }

// AddMonths adds n months and CLAMPS the day to the target month's length
// (Jan 31 + 1 = Feb 28/29), like chrono checked_add_months and Python's
// dateutil relativedelta. Plain t.AddDate(0, n, 0) would overflow instead.
func AddMonths(t time.Time, n int) time.Time {
	y, m, d := t.Date()
	first := time.Date(y, m+time.Month(n), 1, t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), t.Location())
	if dim := DaysInMonth(first.Year(), first.Month()); d > dim {
		d = dim
	}
	return first.AddDate(0, 0, d-1)
}

// AddYears adds n years with the same clamping (Feb 29 + 1 year = Feb 28).
func AddYears(t time.Time, n int) time.Time { return AddMonths(t, 12*n) }

// FirstOfMonth returns day 1 of t's month.
func FirstOfMonth(t time.Time) time.Time { return Date(t.Year(), t.Month(), 1) }

// FirstOfNextMonth returns day 1 of the following month (Dec -> Jan next year).
func FirstOfNextMonth(t time.Time) time.Time { return Date(t.Year(), t.Month()+1, 1) }

// LastOfMonth returns the last day of t's month (day 0 of next month).
func LastOfMonth(t time.Time) time.Time { return Date(t.Year(), t.Month()+1, 0) }

// NthWeekdayOfMonth: n = 1..5 from the start, -1 = last, -2 = second-to-last.
// ok is false when it does not exist (e.g. a 5th Monday).
func NthWeekdayOfMonth(y int, m time.Month, wd time.Weekday, n int) (time.Time, bool) {
	var t time.Time
	switch {
	case n > 0:
		first := Date(y, m, 1)
		t = first.AddDate(0, 0, (int(wd)-int(first.Weekday())+7)%7+7*(n-1))
	case n < 0:
		last := Date(y, m+1, 0)
		t = last.AddDate(0, 0, -((int(last.Weekday())-int(wd)+7)%7 + 7*(-n-1)))
	default:
		return time.Time{}, false
	}
	return t, t.Month() == m && t.Year() == y
}

// NextWeekday returns the first wd strictly after t ("next Monday").
func NextWeekday(t time.Time, wd time.Weekday) time.Time {
	ahead := (int(wd) - int(t.Weekday()) + 7) % 7
	if ahead == 0 {
		ahead = 7
	}
	return t.AddDate(0, 0, ahead)
}

// WeekdayOnOrAfter returns t itself if it is wd, else the next wd.
func WeekdayOnOrAfter(t time.Time, wd time.Weekday) time.Time {
	return t.AddDate(0, 0, (int(wd)-int(t.Weekday())+7)%7)
}

// PrevWeekday returns the most recent wd strictly before t ("last Wednesday").
func PrevWeekday(t time.Time, wd time.Weekday) time.Time {
	back := (int(t.Weekday()) - int(wd) + 7) % 7
	if back == 0 {
		back = 7
	}
	return t.AddDate(0, 0, -back)
}

// StartOfISOWeek returns the Monday of t's ISO week.
func StartOfISOWeek(t time.Time) time.Time {
	return t.AddDate(0, 0, -((int(t.Weekday()) + 6) % 7))
}

// DaysBetween returns b - a in whole calendar days. Converts both to civil
// UTC dates first, so DST and clock times cannot cause off-by-one errors.
func DaysBetween(a, b time.Time) int {
	return int(Civil(b).Sub(Civil(a)).Hours() / 24)
}

// IsBusinessDay reports Mon-Fri (add your holiday set if you have one).
func IsBusinessDay(t time.Time) bool {
	wd := t.Weekday()
	return wd != time.Saturday && wd != time.Sunday
}

// AddBusinessDays moves n business days; from a Saturday, +1 is Monday.
func AddBusinessDays(t time.Time, n int) time.Time {
	step := 1
	if n < 0 {
		step, n = -1, -n
	}
	for i := 0; i < n; i++ {
		t = t.AddDate(0, 0, step)
		for !IsBusinessDay(t) {
			t = t.AddDate(0, 0, step)
		}
	}
	return t
}

// BusinessDaysBetween counts Mon-Fri in the half-open range [a, b);
// negative when b is before a.
func BusinessDaysBetween(a, b time.Time) int {
	sign := 1
	if b.Before(a) {
		a, b, sign = b, a, -1
	}
	total := DaysBetween(a, b)
	weeks, rem := total/7, total%7
	count := weeks * 5
	for i := 0; i < rem; i++ {
		if IsBusinessDay(a.AddDate(0, 0, weeks*7+i)) {
			count++
		}
	}
	return sign * count
}

// EveryNDays: occurrence k = start + k*step. includeStart=false gives
// "every 2 weeks AFTER <date>" (first result is start+step).
func EveryNDays(start time.Time, step int, includeStart bool, count int) []time.Time {
	k0 := 1
	if includeStart {
		k0 = 0
	}
	out := make([]time.Time, 0, count)
	for k := k0; k < k0+count; k++ {
		out = append(out, start.AddDate(0, 0, k*step))
	}
	return out
}

// EveryNMonths computes each occurrence from the START (start + k*n months,
// clamped), so Jan 31 gives Feb 28, Mar 31, Apr 30 - no drift to the 28th.
func EveryNMonths(start time.Time, n int, includeStart bool, count int) []time.Time {
	k0 := 1
	if includeStart {
		k0 = 0
	}
	out := make([]time.Time, 0, count)
	for k := k0; k < k0+count; k++ {
		out = append(out, AddMonths(start, k*n))
	}
	return out
}

// EasterWestern returns Western Easter Sunday (anonymous Gregorian algorithm).
func EasterWestern(y int) time.Time {
	a := y % 19
	b, c := y/100, y%100
	d, e := b/4, b%4
	f := (b + 8) / 25
	g := (b - f + 1) / 3
	h := (19*a + b - d - g + 15) % 30
	i, k := c/4, c%4
	l := (32 + 2*e + 2*i - h - k) % 7
	m := (a + 11*h + 22*l) / 451
	return Date(y, time.Month((h+l-7*m+114)/31), (h+l-7*m+114)%31+1)
}

// EasterOrthodox returns Orthodox Easter (Julian computus) as a Gregorian date.
func EasterOrthodox(y int) time.Time {
	a, b, c := y%4, y%7, y%19
	d := (19*c + 15) % 30
	e := (2*a + 4*b - d + 34) % 7
	month := (d + e + 114) / 31
	day := (d+e+114)%31 + 1
	return FromRD(FixedFromJulian(y, month, day))
}
